head.script:
scwin.onpageload = function() {
    console.log('main.xml');
    localStorage.setItem("log1", 'main.xml');
    wfr.setSrc("wframe_onpageload_loop_WEFF-336_(WSQ-3670)_sub1.xml");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'main.xml'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log2') == 'wincon_sub1.xml'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log3') == 'wfr1_sub2.xml'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log1')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log2')");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log3')");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
